# Shot plans for the two SkilloraClouds panel tutorials. Line numbers are 1-based VO lines of vo/vX_lines.txt.
# refs: 19 = start of line 19; 19.6 = 60% into line 19; "19:शब्द" = when that word is spoken (Whisper word time,
#       else proportional by the word's position in the line text).
# kinds: title | card | rec | shot | outro.  rec clips: dict(src, range=(a,b) in recording s, until=ref (next clip starts),
#       play_at=ref (hold the first frame until then, play at 1x, freeze at the end), clicks=[rec s]).
# calls: (ref, label, (x, y) in source px [, clip index, colour 'g'|'r'])  -> arrow + label at that word.
CHEV = '<svg class="chev" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'

def path(*parts):
    return CHEV.join(f"<span>{p}</span>" for p in parts)

